window.TM_DATA={"asof":"2026-10-16","tools":[{"id":"slurm","name":"Slurm","layer":"hpc","owner":"SchedMD (part of NVIDIA since December 2025)","repo":"SchedMD/slurm","status":"active","why":"Releases every few weeks (26.05.x line, with 25.11 and 25.05 still patched); NVIDIA acquired SchedMD in December 2025 and said Slurm stays open source and vendor neutral.","one":"The batch scheduler of most supercomputers and many GPU training clusters: a controller (slurmctld) queues jobs and hands out whole nodes or slices of them.","what":"slurmctld holds the queue and runs the priority and backfill scheduler; slurmd on each node launches job steps; slurmdbd keeps accounting for fairshare. You write a batch script with #SBATCH lines (nodes, GPUs, time limit) and srun starts one process per task with SLURM_PROCID, SLURM_NODELIST and friends set. Since 25.11 slurmctld can serve OpenMetrics for Prometheus itself (MetricsType=metrics/openmetrics, gauges only), where older versions need an exporter.","when":"A fixed GPU cluster shared by researchers running long multi-node jobs; the default at national labs, universities and many AI labs.","avoid":"Many small services, autoscaling inference, or teams that already run everything on Kubernetes (then Slinky, SUNK or Kueue).","verdict":"Still the default for big synchronous training; learn sbatch, srun, squeue, sacct and scontrol first.","src":[["SchedMD/slurm","https://github.com/SchedMD/slurm"],["NVIDIA blog: NVIDIA acquires SchedMD (2025-12-15)","https://blogs.nvidia.com/blog/nvidia-acquires-schedmd/"],["heise: NVIDIA acquires SchedMD","https://heise.de/-11115881"]],"m":{"repo":"SchedMD/slurm","ghLic":"NOASSERTION","archived":false,"pushed":"2026-10-15","created":"2011-06-20","stars":4441,"commit":"2026-10-15","commitMsg":"Merge branch 'wickberg/refactor-args' into 'master'","ghRel":"v26.05.5","ghRelDate":"2026-10-13","ver":"v26.05.5","verDate":"2026-10-13","verSrc":"https://github.com/SchedMD/slurm/releases","lic":"GPL-2.0 (COPYING: GNU General Public License)","last":"2026-10-15"}},{"id":"openpbs","name":"OpenPBS / PBS Professional","layer":"hpc","owner":"Altair (part of Siemens since March 2025)","repo":"openpbs/openpbs","status":"quiet","why":"Last OpenPBS release v23.06.06 (2023-08-16); occasional commits (latest 2026-04-10). The commercial PBS Professional continues under Altair, which Siemens completed buying on 2025-03-26.","one":"The other long-lived HPC batch scheduler (Portable Batch System), with qsub and #PBS directives instead of sbatch and #SBATCH.","what":"A server (pbs_server), scheduler (pbs_sched) and per-node MoMs (pbs_mom). Same model as Slurm: queues, node resources, priorities, backfill.","when":"You join a site that already runs it (some national and engineering HPC centres).","avoid":"A new GPU training cluster: Slurm has the GPU features, the community and the cloud integrations.","verdict":"Meet it on legacy HPC systems; translate qsub to sbatch in your head and move on.","src":[["openpbs/openpbs","https://github.com/openpbs/openpbs"],["Siemens completes Altair acquisition (2025-03-26), NAFEMS","https://www.nafems.org/about-us/media/news/industrynews1003/siemens-completes-10-billion-acquisition-of-altair-engineering/"]],"m":{"repo":"openpbs/openpbs","ghLic":"NOASSERTION","archived":false,"pushed":"2026-04-10","created":"2016-05-18","stars":808,"commit":"2026-04-10","commitMsg":"Fixed compilation errors and warnings (#2714)","ghRel":"v23.06.06","ghRelDate":"2023-08-16","ver":"v23.06.06","verDate":"2023-08-16","verSrc":"https://github.com/openpbs/openpbs/releases","lic":"AGPL-3.0 (OpenPBS LICENSE); PBS Professional is the commercial build","last":"2026-04-10"}},{"id":"lsf","name":"IBM LSF","layer":"hpc","owner":"IBM","status":"commercial","why":"Commercial product sold by IBM (formerly Spectrum LSF); no public repository, so no release or commit dates can be read here.","one":"IBM's commercial batch scheduler (Load Sharing Facility), common in chip design and some enterprise HPC.","what":"bsub to submit, bjobs to watch; a master batch daemon schedules onto hosts; GPU-aware scheduling and a fairshare model similar to Slurm's.","when":"Enterprise sites that already license it (EDA, finance, some pharma).","avoid":"Anywhere you choose freely: licence cost and a small open community.","verdict":"Know it exists and that bsub is its sbatch; you will rarely pick it for ML.","src":[["IBM LSF product page","https://www.ibm.com/products/hpc-workload-management"]],"m":{"lic":"proprietary (IBM)","last":""}},{"id":"flux","name":"Flux","layer":"hpc","owner":"Lawrence Livermore National Laboratory","repo":"flux-framework/flux-core","status":"active","why":"flux-core v0.90.0 on 2026-10-07; commits daily.","one":"A newer HPC resource manager from LLNL built as a hierarchy of schedulers, so a job can run its own scheduler inside its allocation.","what":"Fully hierarchical: a Flux instance can start child instances that schedule the many small tasks of a workflow (ensembles, AI-for-science pipelines) without loading a central controller. Also runs on Kubernetes (Flux Operator).","when":"Workflows of thousands of small jobs inside a big allocation; LLNL and DOE systems.","avoid":"Plain multi-node training on a standard cluster: Slurm is simpler and everywhere.","verdict":"Interesting design to know for interviews about scheduler scalability; niche outside DOE labs.","src":[["flux-framework/flux-core","https://github.com/flux-framework/flux-core"]],"m":{"repo":"flux-framework/flux-core","ghLic":"LGPL-3.0","archived":false,"pushed":"2026-10-15","created":"2014-09-26","stars":215,"commit":"2026-10-15","commitMsg":"Merge pull request #7845 from garlick/sdexec_naming","ghRel":"v0.90.0","ghRelDate":"2026-10-07","ver":"v0.90.0","verDate":"2026-10-07","verSrc":"https://github.com/flux-framework/flux-core/releases","lic":"LGPL-3.0","last":"2026-10-15"}},{"id":"k8s","name":"Kubernetes","layer":"k8s","owner":"CNCF (Kubernetes project)","repo":"kubernetes/kubernetes","status":"active","why":"Minor releases about three times a year (v1.37.1 on 2026-09-23; v1.38 in alpha); Dynamic Resource Allocation (DRA) went GA in v1.34 (2025-09-01 blog).","one":"The container orchestrator: you declare pods (containers plus resources) and controllers keep the cluster matching that declaration.","what":"The API server stores objects in etcd; the default scheduler binds each pod to a node one pod at a time (filter then score); the kubelet on the node starts the containers; device plugins (or DRA drivers) advertise GPUs as nvidia.com/gpu. Batch training needs add-ons for queueing and gang scheduling: Kueue, JobSet, Volcano or KAI.","when":"Your company already runs services on it, you need autoscaling, mixed training and inference, or cloud-managed clusters (GKE, EKS, AKS).","avoid":"A small research group with one fixed GPU cluster and no platform team: Slurm is less to operate.","verdict":"The platform most ML infrastructure is now built on; on its own it does not queue or gang-schedule jobs.","src":[["kubernetes/kubernetes","https://github.com/kubernetes/kubernetes"],["Kubernetes v1.34: DRA has graduated to GA","https://kubernetes.io/blog/2025/09/01/kubernetes-v1-34-dra-updates/"]],"m":{"repo":"kubernetes/kubernetes","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-16","created":"2014-06-06","stars":128237,"commit":"2026-10-16","commitMsg":"Merge pull request #142760 from Jefftree/sharding-client-helpers","ghRel":"v1.37.1","ghRelDate":"2026-09-23","ver":"v1.37.1","verDate":"2026-09-23","verSrc":"https://github.com/kubernetes/kubernetes/releases","lic":"Apache-2.0","last":"2026-10-16"}},{"id":"kueue","name":"Kueue","layer":"k8s","owner":"Kubernetes SIG Scheduling (kubernetes-sigs)","repo":"kubernetes-sigs/kueue","status":"active","why":"v0.20.2 on 2026-10-15; v0.20 stopped serving the kueue.x-k8s.io/v1beta1 API (manifests must use v1beta2).","one":"Job queueing for Kubernetes: decides when a whole job may start (admission) against quotas, then lets the normal scheduler place its pods.","what":"ClusterQueues hold quota per resource flavour (e.g. H100 vs A100), LocalQueues are per namespace, cohorts let queues borrow unused quota; a job stays suspended until all its pods fit (all-or-nothing admission), with preemption, fair sharing and topology-aware scheduling (TAS). Works with batch Jobs, JobSet, Kubeflow TrainJob, RayJob, LeaderWorkerSet and plain pods.","when":"Sharing a Kubernetes GPU cluster between teams with quotas; the upstream answer to 'Slurm-like queueing on Kubernetes'.","avoid":"Expecting it to place pods by itself: it admits, the kube-scheduler binds.","verdict":"The default batch layer for new Kubernetes training clusters; read the release notes, the API moved to v1beta2 in 0.20.","src":[["kubernetes-sigs/kueue","https://github.com/kubernetes-sigs/kueue"],["Kueue v0.20 changelog (v1beta1 no longer served)","https://github.com/kubernetes-sigs/kueue/blob/main/CHANGELOG/CHANGELOG-0.20.md"]],"m":{"repo":"kubernetes-sigs/kueue","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2022-02-16","stars":3064,"commit":"2026-10-15","commitMsg":"docs: extend TAS documentation with LWS podset grouping examples (#13…","ghRel":"v0.20.2","ghRelDate":"2026-10-15","ver":"v0.20.2","verDate":"2026-10-15","verSrc":"https://github.com/kubernetes-sigs/kueue/releases","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"jobset","name":"JobSet","layer":"k8s","owner":"Kubernetes SIG Apps / WG Batch (kubernetes-sigs)","repo":"kubernetes-sigs/jobset","status":"active","why":"v0.13.0 on 2026-10-12; Kubeflow Trainer v2 builds every TrainJob as a JobSet.","one":"A Kubernetes API for a group of Jobs that form one distributed workload (e.g. a driver plus workers), with one headless service for peer discovery.","what":"replicatedJobs describe each role; JobSet creates the Jobs, a headless Service so pods find each other by DNS name (the rendezvous address for torchrun), success and failure policies (restart the whole set when one pod fails), and exclusive placement per topology domain.","when":"Multi-node PyTorch or JAX training on Kubernetes without a framework-specific operator.","avoid":"Single-pod jobs (a plain Job is enough).","verdict":"The building block underneath most modern Kubernetes training APIs; worth writing one by hand.","src":[["kubernetes-sigs/jobset","https://github.com/kubernetes-sigs/jobset"],["Red Hat: each TrainJob is translated into a JobSet (2026-09-29)","https://developers.redhat.com/articles/2026/09/29/distributed-training-openshift-ai-34-kubeflow-trainer-v2"]],"m":{"repo":"kubernetes-sigs/jobset","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-16","created":"2023-03-31","stars":346,"commit":"2026-10-16","commitMsg":"Fix stale JobSet deletion during TTL cleanup (#1356)","ghRel":"v0.13.0","ghRelDate":"2026-10-12","ver":"v0.13.0","verDate":"2026-10-12","verSrc":"https://github.com/kubernetes-sigs/jobset/releases","lic":"Apache-2.0","last":"2026-10-16"}},{"id":"volcano","name":"Volcano","layer":"k8s","owner":"CNCF incubating project (started at Huawei)","repo":"volcano-sh/volcano","status":"active","why":"v1.16.0 on 2026-10-15; CNCF incubating since March 2022.","one":"A batch scheduler that replaces the Kubernetes scheduler for batch pods, with gang scheduling, queues and fair share.","what":"Its own scheduler (vc-scheduler) with plugins (gang, proportion, drf, binpack, topology), a Volcano Job CRD and PodGroups so a job's pods are bound all at once or not at all.","when":"Clusters that want scheduler-level gang scheduling and HPC-style policies; common in China and with Spark or MPI workloads.","avoid":"Running it beside Kueue on the same pods; pick one batch layer.","verdict":"Mature alternative to Kueue; it swaps the scheduler, Kueue keeps the default one.","src":[["volcano-sh/volcano","https://github.com/volcano-sh/volcano"],["CNCF: Volcano moves to the incubator (2022-04-07)","https://www.cncf.io/blog/2022/04/07/cloud-native-batch-system-volcano-moves-to-the-cncf-incubator/"]],"m":{"repo":"volcano-sh/volcano","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2019-03-14","stars":6020,"commit":"2026-10-15","commitMsg":"Merge pull request #6098 from xsvm/fix/audit-exporter-go-version","ghRel":"v1.16.0","ghRelDate":"2026-10-15","ver":"v1.16.0","verDate":"2026-10-15","verSrc":"https://github.com/volcano-sh/volcano/releases","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"yunikorn","name":"Apache YuniKorn","layer":"k8s","owner":"Apache Software Foundation","repo":"apache/yunikorn-core","status":"active","why":"v1.10.0 on 2026-10-06; commits daily.","one":"A replacement scheduler for Kubernetes (and YARN) with hierarchical queues and gang scheduling, from the Hadoop world.","what":"Hierarchical queues with guaranteed and maximum resources, application-aware sorting, gang scheduling via placeholders.","when":"Data platforms moving Spark from YARN to Kubernetes that want YARN-like queues.","avoid":"GPU training clusters starting fresh: Kueue and Volcano have more ML integrations.","verdict":"Solid, but its centre of gravity is Spark, not GPU training.","src":[["apache/yunikorn-core","https://github.com/apache/yunikorn-core"]],"m":{"repo":"apache/yunikorn-core","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2019-06-13","stars":1034,"commit":"2026-10-15","commitMsg":"[YUNIKORN-3506] Fix child queue preemptable resource calculation in q…","ghRel":"v1.10.0","ghRelDate":"2026-10-06","ver":"v1.10.0","verDate":"2026-10-06","verSrc":"https://github.com/apache/yunikorn-core/releases","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"kai","name":"KAI Scheduler (open-sourced Run:ai scheduler)","layer":"k8s","owner":"NVIDIA","repo":"NVIDIA/KAI-Scheduler","status":"active","why":"Open-sourced by NVIDIA under Apache-2.0 on 2025-04-01 from the Run:ai platform; v0.18.6 on 2026-10-15; the repository moved to the kai-scheduler organisation.","one":"The Run:ai GPU scheduler as an open-source Kubernetes scheduler: gang scheduling, hierarchical queues, GPU sharing and fractions.","what":"Queues with quotas and over-quota borrowing, fairness (DRF), consolidation and bin packing to fight fragmentation, GPU sharing, a podgrouper that understands Kubeflow, Ray, Argo and Training Operator jobs.","when":"GPU-heavy Kubernetes clusters that want Run:ai-style scheduling without the commercial platform.","avoid":"Mixing it with Volcano or another replacement scheduler on the same pods.","verdict":"The serious third option beside Kueue and Volcano, backed by NVIDIA.","src":[["NVIDIA blog: NVIDIA open sources Run:ai scheduler (2025-04-01)","https://developer.nvidia.com/blog/nvidia-open-sources-runai-scheduler-to-foster-community-collaboration/"],["kai-scheduler/KAI-Scheduler","https://github.com/kai-scheduler/KAI-Scheduler"]],"m":{"repo":"kai-scheduler/KAI-Scheduler","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2025-02-26","stars":1582,"commit":"2026-10-15","commitMsg":"ci: build PR images in parallel (#2434)","ghRel":"v0.18.6","ghRelDate":"2026-10-15","ver":"v0.18.6","verDate":"2026-10-15","verSrc":"https://github.com/kai-scheduler/KAI-Scheduler/releases","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"trainer","name":"Kubeflow Trainer v2 (TrainJob)","layer":"k8s","owner":"Kubeflow (CNCF)","repo":"kubeflow/trainer","status":"active","why":"v2.0 released July 2025, v2.3.0 on 2026-08-07; the README still calls the project alpha ('APIs may change'). The Python SDK is the separate kubeflow package on PyPI.","one":"One TrainJob API for PyTorch, JAX, DeepSpeed, MLX and more, backed by reusable runtimes, replacing the per-framework PyTorchJob/TFJob/MPIJob of Training Operator v1.","what":"Platform admins publish ClusterTrainingRuntimes (image, launcher, MPI or torchrun settings); users submit a TrainJob naming a runtime and the number of nodes. The controller turns it into a JobSet; Kueue can admit it.","when":"Teams on Kubernetes that want a training-job API for data scientists, with the platform team owning the runtime.","avoid":"Production-critical API stability: still alpha by its own README.","verdict":"Where Kubeflow training is going; prefer it to v1 for anything new.","src":[["kubeflow/trainer README (news, V1 note)","https://github.com/kubeflow/trainer"],["Kubeflow blog: Introducing Trainer V2","https://blog.kubeflow.org/trainer/intro/"],["Migrating to Trainer v2","https://www.kubeflow.org/docs/components/trainer/operator-guides/migration/"]],"m":{"repo":"kubeflow/trainer","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2017-06-28","stars":2245,"commit":"2026-10-15","commitMsg":"chore: update controller tools to v0.23 and drop crdschema hack (#4249","ghRel":"v2.3.0","ghRelDate":"2026-08-07","ver":"v2.3.0","verDate":"2026-08-07","verSrc":"https://github.com/kubeflow/trainer/releases","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"trainerv1","name":"Kubeflow Training Operator v1 (PyTorchJob)","layer":"k8s","owner":"Kubeflow (CNCF)","repo":"kubeflow/trainer","pypi":"kubeflow-training","status":"maintenance","why":"Kubeflow 'will maintain the Training Operator V1 source code at the release-1.9 branch' (v1.9.4, 2026-08-18); Kueue calls Trainer v1 'legacy' and its PyTorchJob integration deprecated, removal tentatively v0.20.","one":"The older Kubeflow operator with one CRD per framework: PyTorchJob, TFJob, XGBoostJob, PaddleJob, JAXJob (MPIJob lives in mpi-operator).","what":"A PyTorchJob lists Master and Worker replica specs; the operator creates pods and services and sets MASTER_ADDR, MASTER_PORT, WORLD_SIZE and RANK for torchrun. Still the API in most blog posts and many production clusters.","when":"Maintaining existing PyTorchJobs.","avoid":"New work: migrate to TrainJob (v2) or write a JobSet.","verdict":"Read it, run it where it exists, do not start new projects on it.","src":[["kubeflow/trainer README: Training Operator V1","https://github.com/kubeflow/trainer#kubeflow-training-operator-v1"],["Kueue: Kubeflow Jobs (v1) deprecation notice","https://kueue.sigs.k8s.io/docs/tasks/run/kubeflow/"]],"m":{"ver":"1.9.4","verDate":"2026-08-18","verSrc":"https://pypi.org/project/kubeflow-training/","first":"2021-10-16","nrel":18,"pypiLic":"Apache License Version 2.0","repo":"kubeflow/trainer","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2017-06-28","stars":2245,"commit":"2026-10-15","commitMsg":"chore: update controller tools to v0.23 and drop crdschema hack (#4249","ghRel":"v1.9.4","ghRelDate":"2026-08-18","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"mpiop","name":"MPI Operator (MPIJob)","layer":"k8s","owner":"Kubeflow (CNCF)","repo":"kubeflow/mpi-operator","status":"maintained","why":"v0.8.2 on 2026-07-03; commits in October 2026.","one":"Runs MPI-style jobs on Kubernetes: a launcher pod calls mpirun, which reaches worker pods over SSH.","what":"Generates the hostfile and SSH keys, starts workers, then the launcher runs mpirun (or deepspeed's launcher). Used for DeepSpeed and Horovod style jobs.","when":"Code that expects mpirun or the deepspeed multi-node launcher with a hostfile.","avoid":"Plain torchrun jobs: JobSet or TrainJob need no SSH.","verdict":"Still useful for MPI-shaped jobs; most PyTorch training no longer needs it.","src":[["kubeflow/mpi-operator","https://github.com/kubeflow/mpi-operator"]],"m":{"repo":"kubeflow/mpi-operator","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-13","created":"2018-05-26","stars":539,"commit":"2026-10-02","commitMsg":"Fix the Enum marker on launcherCreationPolicy (#869)","ghRel":"v0.8.2","ghRelDate":"2026-07-03","ver":"v0.8.2","verDate":"2026-07-03","verSrc":"https://github.com/kubeflow/mpi-operator/releases","lic":"Apache-2.0","last":"2026-10-02"}},{"id":"kuberay","name":"KubeRay","layer":"k8s","owner":"Ray project (Anyscale)","repo":"ray-project/kuberay","status":"active","why":"v1.7.1 on 2026-09-21; commits daily.","one":"The Kubernetes operator for Ray: RayCluster, RayJob and RayService custom resources.","what":"Creates a head pod and worker groups, autoscales workers with the Ray autoscaler, and for RayJob submits your entrypoint and tears the cluster down at the end. Kueue can admit RayJobs.","when":"Running Ray (training, data, serving) on a Kubernetes cluster.","avoid":"A laptop or a single VM: ray start or ray.init is enough.","verdict":"The standard way to run Ray in production on Kubernetes.","src":[["ray-project/kuberay","https://github.com/ray-project/kuberay"]],"m":{"repo":"ray-project/kuberay","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2020-10-29","stars":2727,"commit":"2026-10-15","commitMsg":"[Feature][History Server] Make the collector image configurable on th…","ghRel":"v1.7.1","ghRelDate":"2026-09-21","ver":"v1.7.1","verDate":"2026-09-21","verSrc":"https://github.com/ray-project/kuberay/releases","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"gpuop","name":"NVIDIA GPU Operator and k8s device plugin","layer":"k8s","owner":"NVIDIA","repo":"NVIDIA/gpu-operator","status":"active","why":"GPU Operator 26.7.2 on 2026-10-14; the device plugin (NVIDIA/k8s-device-plugin) v0.20.1 on 2026-09-22.","one":"Installs everything a Kubernetes node needs to run GPU pods: driver, container toolkit, device plugin, DCGM exporter, GPU feature discovery, MIG manager.","what":"The device plugin advertises nvidia.com/gpu to the kubelet so pods can request GPUs; the operator manages the rest as DaemonSets. NVIDIA also ships a DRA driver for the newer DRA API.","when":"Any Kubernetes cluster with NVIDIA GPUs (managed clouds often preinstall parts of it).","avoid":"Hand-installing drivers per node on Kubernetes.","verdict":"Plumbing every GPU Kubernetes cluster has; know what each DaemonSet does when a node shows zero GPUs.","src":[["NVIDIA/gpu-operator","https://github.com/NVIDIA/gpu-operator"],["NVIDIA/k8s-device-plugin","https://github.com/NVIDIA/k8s-device-plugin"]],"m":{"repo":"NVIDIA/gpu-operator","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2019-02-26","stars":2931,"commit":"2026-10-15","commitMsg":"Merge pull request #3028 from shin4141/codex/3026-native-sidecar-gpu-…","ghRel":"26.7.2","ghRelDate":"2026-10-14","ver":"26.7.2","verDate":"2026-10-14","verSrc":"https://github.com/NVIDIA/gpu-operator/releases","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"armada","name":"Armada","layer":"k8s","owner":"G-Research (CNCF sandbox)","repo":"armadaproject/armada","status":"active","why":"v0.22.14 on 2026-10-14; commits daily.","one":"A multi-cluster batch queue in front of many Kubernetes clusters, built for very high job throughput.","what":"Jobs go to a central Armada server with fair-share queues; executors in each cluster lease work. Gang scheduling across one cluster.","when":"Millions of jobs a day spread over many clusters (its origin at a quantitative trading firm).","avoid":"One cluster: Kueue is simpler.","verdict":"Specialised; good interview example of scheduling above clusters (Kueue's MultiKueue does similar).","src":[["armadaproject/armada","https://github.com/armadaproject/armada"]],"m":{"repo":"armadaproject/armada","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2019-06-19","stars":636,"commit":"2026-10-15","commitMsg":"update dotnet tests and add to ci pipeline (#516) (#5295)","ghRel":"v0.22.14","ghRelDate":"2026-10-14","ver":"v0.22.14","verDate":"2026-10-14","verSrc":"https://github.com/armadaproject/armada/releases","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"ray","name":"Ray (Ray Train, Ray Data)","layer":"orch","owner":"Ray project (Anyscale; PyTorch Foundation project since 2025-10-22)","repo":"ray-project/ray","pypi":"ray","status":"active","why":"Ray 2.59.0 on 2026-10-02 (PyPI), roughly monthly releases; joined the PyTorch Foundation on 2025-10-22.","one":"A Python-native distributed runtime: tasks and actors on a cluster, with libraries for training (Ray Train), data loading (Ray Data), tuning and serving.","what":"A head node runs the GCS (cluster metadata); a raylet per node schedules tasks and owns a shared-memory object store. Ray Train starts one worker actor per GPU in a placement group (gang reserved), sets up torch.distributed for you, and handles checkpoints and restarts.","when":"Pipelines that mix data processing, training and serving in Python; RL and post-training systems with many cooperating processes; heterogeneous CPU and GPU stages.","avoid":"As a replacement for a cluster scheduler between teams: Ray schedules inside one Ray cluster, which itself runs on Kubernetes (KubeRay), Slurm or VMs.","verdict":"The most used Python distributed runtime for ML beyond plain DDP; learn it beside, not instead of, a cluster scheduler.","src":[["ray-project/ray","https://github.com/ray-project/ray"],["PyTorch Foundation welcomes Ray (2025-10-22)","https://pytorch.org/blog/pytorch-foundation-welcomes-ray-to-deliver-a-unified-open-source-ai-compute-stack/"]],"m":{"ver":"2.59.0","verDate":"2026-10-02","verSrc":"https://pypi.org/project/ray/","first":"2017-06-03","nrel":133,"pypiLic":"Apache 2.0","repo":"ray-project/ray","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-16","created":"2016-10-25","stars":44036,"commit":"2026-10-16","commitMsg":"[Data] Untangle the Budget-based Task Submission Logic (#67032)","lic":"Apache-2.0","last":"2026-10-16"}},{"id":"skypilot","name":"SkyPilot","layer":"orch","owner":"SkyPilot project (started at UC Berkeley Sky Computing Lab)","repo":"skypilot-org/skypilot","pypi":"skypilot","status":"active","why":"0.14.0 on 2026-10-05 (PyPI); nightly 1.0.0.dev builds daily.","one":"Run a job described in one YAML on any cloud or Kubernetes cluster it can reach, finding the cheapest available GPUs.","what":"sky launch provisions VMs or pods across clouds and regions, syncs code, runs setup and run commands, can use spot instances with automatic recovery (managed jobs), and sets SKYPILOT_NODE_IPS and SKYPILOT_NODE_RANK for multi-node torchrun.","when":"Small teams renting GPUs from several clouds or neoclouds, chasing availability and price.","avoid":"A fixed on-prem cluster with a scheduler already in place.","verdict":"The best-known multi-cloud launcher; good for startups and research groups without a platform team.","src":[["skypilot-org/skypilot","https://github.com/skypilot-org/skypilot"]],"m":{"ver":"0.14.0","verDate":"2026-10-05","verSrc":"https://pypi.org/project/skypilot/","first":"2022-08-09","nrel":63,"pypiLic":"Apache 2.0","repo":"skypilot-org/skypilot","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-16","created":"2021-08-11","stars":10713,"commit":"2026-10-15","commitMsg":"[Core] Only include SSH credentials in status for clusters the caller…","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"dstack","name":"dstack","layer":"orch","owner":"dstack","repo":"dstackai/dstack","pypi":"dstack","status":"active","why":"0.22.4 on 2026-10-15; releases weekly.","one":"An open-source alternative to Kubernetes and Slurm for GPU workloads: dev environments, tasks and services on clouds or your own servers.","what":"Fleets of cloud or SSH-reachable machines, YAML task definitions, multi-node tasks with DSTACK_MASTER_NODE_IP and DSTACK_NODE_RANK, project quotas.","when":"Teams that want a simple self-hosted control plane over rented and on-prem GPUs.","avoid":"Organisations already standardised on Kubernetes.","verdict":"Credible newcomer; smaller community than SkyPilot.","src":[["dstackai/dstack","https://github.com/dstackai/dstack"]],"m":{"ver":"0.22.4","verDate":"2026-10-15","verSrc":"https://pypi.org/project/dstack/","first":"2021-09-06","nrel":344,"pypiLic":"Mozilla Public License 2.0 (MPL 2.0)","repo":"dstackai/dstack","ghLic":"MPL-2.0","archived":false,"pushed":"2026-10-15","created":"2022-01-04","stars":2283,"commit":"2026-10-15","commitMsg":"Add project quotas to the UI (#4370)","ghRel":"0.22.4","ghRelDate":"2026-10-15","lic":"MPL-2.0","last":"2026-10-15"}},{"id":"runai","name":"NVIDIA Run:ai","layer":"orch","owner":"NVIDIA (acquisition closed 2024-12-30)","status":"commercial","why":"NVIDIA completed the Run:ai acquisition on 2024-12-30 and open-sourced the scheduler at its core as KAI Scheduler on 2025-04-01; the platform is still sold.","one":"A commercial GPU orchestration platform on Kubernetes: quotas, GPU fractions, a UI and workload management for data-science teams.","what":"Adds projects and departments with GPU quotas, over-quota borrowing, fractional GPUs and dashboards on top of Kubernetes; the scheduling engine is KAI.","when":"Enterprises that want a supported product for sharing GPUs.","avoid":"If you only need the scheduling: use KAI Scheduler or Kueue directly.","verdict":"The commercial wrapper; its open core (KAI) is what to learn.","src":[["TechCrunch: Nvidia completes Run:ai acquisition (2024-12-30)","https://techcrunch.com/2024/12/30/nvidia-completes-acquisition-of-ai-infrastructure-startup-runai/"],["NVIDIA: open-sourcing the Run:ai scheduler","https://developer.nvidia.com/blog/nvidia-open-sources-runai-scheduler-to-foster-community-collaboration/"]],"m":{"lic":"proprietary (commercial platform); its scheduler is open source as KAI","last":""}},{"id":"determined","name":"Determined","layer":"orch","owner":"HPE (acquired 2021)","repo":"determined-ai/determined","pypi":"determined","status":"quiet","why":"Last release 0.38.1 on 2025-03-19 and last commit 2025-03-20 (its release notes); no archive flag or notice found, and www.determined.ai now redirects (HTTP 301) to HPE's general AI solutions page (checked 2026-10-16). HPE sold it as HPE Machine Learning Development Environment.","one":"An all-in-one training platform: distributed training, hyperparameter search, experiment tracking and GPU scheduling, open source under Apache-2.0.","what":"A master and agents (or Kubernetes or Slurm as resource manager); you wrap code in its Trial or Core API and it handles launching, checkpoints, pausing and resuming jobs.","when":"Only if you inherit it.","avoid":"New projects: no release or commit for about 19 months by October 2026.","verdict":"Effectively stalled; a lesson that a platform owned by one vendor can stop.","src":[["determined-ai/determined","https://github.com/determined-ai/determined"],["HPE acquires Determined AI (2021-06-21)","https://www.hpe.com/us/en/newsroom/press-release/2021/06/hewlett-packard-enterprise-acquires-determined-ai-to-accelerate-artificial-intelligence-innovation-with-fast-and-simple-machine-learning-modeling.html"]],"m":{"ver":"0.38.1","verDate":"2025-03-19","verSrc":"https://pypi.org/project/determined/","first":"2020-04-08","nrel":607,"pypiLic":"Apache Software License","repo":"determined-ai/determined","ghLic":"Apache-2.0","archived":false,"pushed":"2025-03-20","created":"2020-04-07","stars":3246,"commit":"2025-03-20","commitMsg":"docs: add release notes for 0.38.1 (#10258)","ghRel":"v0.38.1","ghRelDate":"2025-03-19","lic":"Apache-2.0","last":"2025-03-20"}},{"id":"nomad","name":"HashiCorp Nomad","layer":"orch","owner":"HashiCorp (IBM since 2025-02-27)","repo":"hashicorp/nomad","status":"active","why":"v2.0.7 on 2026-09-18; IBM completed buying HashiCorp on 2025-02-27; source-available licence since 2023.","one":"A simpler general workload orchestrator than Kubernetes: one binary schedules containers, VMs and plain processes.","what":"Servers run a scheduler (bin packing or spread) and clients run tasks; supports GPUs through device plugins; batch jobs and system jobs. No gang scheduling built for distributed training.","when":"Organisations already on the HashiCorp stack that want light orchestration.","avoid":"Multi-node training clusters: few ML integrations and a source-available licence.","verdict":"Rare in ML; useful contrast when asked why Kubernetes won.","src":[["hashicorp/nomad LICENSE","https://github.com/hashicorp/nomad/blob/main/LICENSE"],["IBM completes HashiCorp acquisition (TechRepublic)","https://www.techrepublic.com/article/ibm-hashicorp-acquisition-completed/"]],"m":{"repo":"hashicorp/nomad","ghLic":"NOASSERTION","archived":false,"pushed":"2026-10-15","created":"2015-06-01","stars":17012,"commit":"2026-10-15","commitMsg":"fixed array out of bounds error on darwin arm64 client CPU registrati…","ghRel":"v2.0.7","ghRelDate":"2026-09-18","ver":"v2.0.7","verDate":"2026-09-18","verSrc":"https://github.com/hashicorp/nomad/releases","lic":"BUSL-1.1 (Business Source License, from v1.7.0; LICENSE file)","last":"2026-10-15"}},{"id":"torchrun","name":"torchrun (torch.distributed.run)","layer":"launch","owner":"PyTorch (Meta, PyTorch Foundation)","repo":"pytorch/pytorch","pypi":"torch","status":"active","why":"Ships with every PyTorch release (torch 2.14.1 on 2026-09-30).","one":"PyTorch's launcher: starts one process per GPU on each node, runs the rendezvous so they find each other, and restarts them on failure.","what":"torchrun --nnodes --nproc-per-node --rdzv-backend c10d --rdzv-endpoint host:port train.py. An elastic agent per node joins the rendezvous, assigns RANK, LOCAL_RANK and WORLD_SIZE, starts workers, watches them and restarts the group up to --max-restarts times.","when":"Every multi-GPU PyTorch job; schedulers (srun, JobSet, TrainJob) usually just start one torchrun per node.","avoid":"Nothing: if you use something else it often wraps this.","verdict":"The launcher to understand first; the Launch lab traces its rendezvous.","src":[["torchrun docs","https://docs.pytorch.org/docs/stable/elastic/run.html"]],"m":{"ver":"2.14.1","verDate":"2026-09-30","verSrc":"https://pypi.org/project/torch/","first":"2018-12-07","nrel":51,"pypiLic":"Apache-2.0 AND Apache-2.0 WITH LLVM-exception AND BSD-2-Clau","repo":"pytorch/pytorch","ghLic":"NOASSERTION","archived":false,"pushed":"2026-10-16","created":"2016-08-13","stars":104707,"commit":"2026-10-16","commitMsg":"[c10d][cuda graphs] Add collective metadata to NCCL kernels in CUDA g…","lic":"BSD-3-Clause (PyTorch LICENSE)","last":"2026-10-16"}},{"id":"deepspeedl","name":"DeepSpeed launcher (deepspeed)","layer":"launch","owner":"DeepSpeed (LF AI & Data since February 2025; started at Microsoft)","repo":"deepspeedai/DeepSpeed","pypi":"deepspeed","status":"active","why":"0.19.7 on 2026-09-16 (PyPI); Microsoft contributed DeepSpeed to LF AI & Data in February 2025 and the repository moved to the deepspeedai organisation.","one":"The deepspeed command that launches DeepSpeed training on one or many nodes from a hostfile.","what":"Reads a hostfile (host slots=8), reaches the other nodes with pdsh (default) or OpenMPI or MVAPICH, and runs a per-node launcher that sets ranks. On Slurm or Kubernetes it is often replaced by srun or torchrun.","when":"Clusters reached over SSH with a hostfile; DeepSpeed examples.","avoid":"Under a scheduler that already starts processes: use torchrun or srun with DeepSpeed's library.","verdict":"Fine on bare machines; under a scheduler, launch with the scheduler.","src":[["deepspeedai/DeepSpeed","https://github.com/deepspeedai/DeepSpeed"],["LF AI & Data welcomes DeepSpeed (2025-02)","https://lfaidata.foundation/blog/2025/02/03/lf-ai-data-welcomes-deepspeed-advancing-deep-learning-optimization/"]],"m":{"ver":"0.19.7","verDate":"2026-09-16","verSrc":"https://pypi.org/project/deepspeed/","first":"2020-10-22","nrel":132,"pypiLic":"Apache Software License 2.0","repo":"deepspeedai/DeepSpeed","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-16","created":"2020-01-23","stars":43232,"commit":"2026-10-15","commitMsg":"Add a nightly multi-rank CPU suite (#8806)","ghRel":"v0.19.7","ghRelDate":"2026-09-16","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"accelerate","name":"Hugging Face Accelerate (accelerate launch)","layer":"launch","owner":"Hugging Face","repo":"huggingface/accelerate","pypi":"accelerate","status":"active","why":"1.15.0 on 2026-09-09 (PyPI).","one":"A thin layer so the same training script runs on one GPU, DDP, FSDP or DeepSpeed, plus accelerate launch which calls torchrun or deepspeed for you.","what":"accelerate config writes a YAML (machines, processes, mixed precision, FSDP or DeepSpeed settings); accelerate launch turns it into a torchrun or deepspeed command.","when":"Hugging Face Transformers and TRL training scripts.","avoid":"Debugging rendezvous problems: look at the underlying torchrun command it builds.","verdict":"Convenient; know what it expands into.","src":[["huggingface/accelerate","https://github.com/huggingface/accelerate"]],"m":{"ver":"1.15.0","verDate":"2026-09-09","verSrc":"https://pypi.org/project/accelerate/","first":"2020-10-30","nrel":83,"pypiLic":"Apache","repo":"huggingface/accelerate","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-14","created":"2020-10-30","stars":9915,"commit":"2026-10-14","commitMsg":"Fsdp2 keep output dtype (#4403)","ghRel":"v1.15.0","ghRelDate":"2026-09-09","lic":"Apache-2.0","last":"2026-10-14"}},{"id":"ompi","name":"Open MPI (mpirun)","layer":"launch","owner":"Open MPI project","repo":"open-mpi/ompi","status":"active","why":"v5.0.11 on 2026-08-25; v6.0.0 at release candidate 2 (2026-10-01).","one":"The MPI library and launcher of HPC: mpirun starts N copies of a program across hosts and wires them together.","what":"mpirun -np 16 -H a:8,b:8 python train.py; ranks come from OMPI_COMM_WORLD_RANK. PyTorch can read them, and Horovod and DeepSpeed can launch through it. Under Slurm, srun replaces mpirun via PMIx.","when":"MPI programs, Horovod, the MPI Operator, some HPC sites.","avoid":"Plain PyTorch DDP: torchrun or srun is simpler.","verdict":"Know the vocabulary (ranks, hostfiles, PMIx); you rarely need it for PyTorch.","src":[["open-mpi/ompi","https://github.com/open-mpi/ompi"]],"m":{"repo":"open-mpi/ompi","ghLic":"NOASSERTION","archived":false,"pushed":"2026-10-15","created":"2014-09-16","stars":2667,"commit":"2026-10-15","commitMsg":"Merge pull request #14652 from hppritcha/fix_CID_1703283","ghRel":"v5.0.11","ghRelDate":"2026-08-25","ver":"v5.0.11","verDate":"2026-08-25","verSrc":"https://github.com/open-mpi/ompi/releases","lic":"BSD-3-Clause style (LICENSE)","last":"2026-10-15"}},{"id":"pdsh","name":"pdsh","layer":"launch","owner":"LLNL (chaos project)","repo":"chaos/pdsh","status":"maintained","why":"pdsh-2.36 on 2026-01-12, the first release in years; small maintenance commits.","one":"Parallel shell: run one command on many hosts over SSH at once.","what":"pdsh -w node[01-16] nvidia-smi. DeepSpeed's launcher uses it by default to start per-node launchers.","when":"Quick checks across nodes; DeepSpeed's default multi-node launch.","avoid":"As a job launcher under a scheduler.","verdict":"An admin tool worth knowing; not a scheduler.","src":[["chaos/pdsh","https://github.com/chaos/pdsh"]],"m":{"repo":"chaos/pdsh","ghLic":"GPL-2.0","archived":false,"pushed":"2026-01-12","created":"2015-05-11","stars":569,"commit":"2026-01-12","commitMsg":"Merge pull request #176 from grondo/mergify-update","ghRel":"2.36","ghRelDate":"2026-01-12","ver":"2.36","verDate":"2026-01-12","verSrc":"https://github.com/chaos/pdsh/releases","lic":"GPL-2.0","last":"2026-01-12"}},{"id":"torchx","name":"TorchX","layer":"launch","owner":"Meta (meta-pytorch)","repo":"pytorch/torchx","pypi":"torchx","status":"maintained","why":"Last PyPI release 0.7.0 on 2024-07-16, but commits continue (2026-09-28) after the move to the meta-pytorch organisation.","one":"A universal job launcher for PyTorch apps: one component definition, submitted to Slurm, Kubernetes, Docker or local.","what":"torchx run -s slurm dist.ddp -j 2x8 train.py; schedulers are plugins; the dist.ddp component wraps torchrun.","when":"Teams that want one CLI over several backends.","avoid":"Depending on a recent release: the PyPI package is over two years old.","verdict":"Useful idea, slow releases; check main before relying on it.","src":[["meta-pytorch/torchx","https://github.com/meta-pytorch/torchx"]],"m":{"ver":"0.7.0","verDate":"2024-07-16","verSrc":"https://pypi.org/project/torchx/","first":"2021-06-16","nrel":17,"pypiLic":"BSD-3","repo":"meta-pytorch/torchx","ghLic":"NOASSERTION","archived":false,"pushed":"2026-10-14","created":"2021-05-04","stars":428,"commit":"2026-09-28","commitMsg":"Accept dataclass values in scheduler overlays","ghRel":"v0.7.0","ghRelDate":"2024-07-16","lic":"BSD-3-Clause","last":"2026-09-28"}},{"id":"submitit","name":"submitit","layer":"launch","owner":"Meta (facebookincubator)","repo":"facebookincubator/submitit","pypi":"submitit","status":"maintained","why":"1.5.4 on 2025-12-17; occasional commits.","one":"Submit Python functions to Slurm from Python and get results back as futures.","what":"executor = submitit.AutoExecutor(folder); executor.update_parameters(nodes=2, gpus_per_node=8); job = executor.submit(fn). Pickles the function, writes the sbatch script, handles preemption by checkpointing and requeueing.","when":"Research code on Slurm launched from notebooks or sweeps (common in Meta research repos).","avoid":"Non-Slurm clusters.","verdict":"Small and dependable; the cleanest way to drive Slurm from Python.","src":[["facebookincubator/submitit","https://github.com/facebookincubator/submitit"]],"m":{"ver":"1.5.4","verDate":"2025-12-17","verSrc":"https://pypi.org/project/submitit/","first":"2020-04-24","nrel":26,"pypiLic":"MIT License","repo":"facebookincubator/submitit","ghLic":"MIT","archived":false,"pushed":"2026-01-14","created":"2020-04-24","stars":1642,"commit":"2026-01-14","commitMsg":"Activate CI on PRs (#1805)","ghRel":"1.5.4","ghRelDate":"2025-12-17","lic":"MIT","last":"2026-01-14"}},{"id":"slinky","name":"Slinky (Slurm on Kubernetes)","layer":"cloud","owner":"SchedMD (NVIDIA)","repo":"SlinkyProject/slurm-operator","status":"active","why":"Announced by SchedMD in 2024 (Apache-2.0); 1.0 in late 2025; slurm-operator release v1.2.3 on 2026-09-30.","one":"SchedMD's own projects for running Slurm inside Kubernetes: slurm-operator (Slurm clusters as Kubernetes objects) and slurm-bridge (Slurm scheduling Kubernetes pods).","what":"slurm-operator runs slurmctld, slurmd NodeSets and login nodes as pods with CRDs; slurm-bridge lets Slurm be the scheduler for Kubernetes workloads so both share one GPU pool.","when":"A Kubernetes platform team that must give researchers sbatch.","avoid":"If researchers are happy with Kubernetes-native jobs.","verdict":"The vendor-supported way to have both; younger than SUNK.","src":[["Slinky docs (SchedMD)","https://slurm.schedmd.com/slinky.html"],["SlinkyProject/slurm-operator","https://github.com/SlinkyProject/slurm-operator"]],"m":{"repo":"SlinkyProject/slurm-operator","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2024-11-05","stars":373,"commit":"2026-10-15","commitMsg":"Merge branch 'mwarnicke/nodeset-nil-annotations' into 'main'","ghRel":"v1.2.3","ghRelDate":"2026-09-30","ver":"v1.2.3","verDate":"2026-09-30","verSrc":"https://github.com/SlinkyProject/slurm-operator/releases","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"sunk","name":"CoreWeave SUNK","layer":"cloud","owner":"CoreWeave","status":"commercial","why":"Offered as a CoreWeave product (Slurm on Kubernetes) since 2023; no public repository.","one":"CoreWeave's Slurm on Kubernetes: Slurm nodes are pods on CoreWeave Kubernetes Service, so training and inference share one cluster.","what":"A Slurm scheduler plugin for Kubernetes and a CRD for Slurm nodes; Slurm accounting in MySQL; tied into CoreWeave's node health checks and lifecycle.","when":"Renting large clusters from CoreWeave.","avoid":"Outside CoreWeave (use Slinky).","verdict":"Proof that big labs want sbatch on Kubernetes; product, not a project.","src":[["CoreWeave: SUNK","https://coreweave.com/products/sunk"],["CoreWeave docs: SUNK","https://docs.coreweave.com/products/sunk"]],"m":{"lic":"proprietary (CoreWeave service)","last":""}},{"id":"pcluster","name":"AWS ParallelCluster","layer":"cloud","owner":"AWS","repo":"aws/aws-parallelcluster","pypi":"aws-parallelcluster","status":"active","why":"3.16.1 on 2026-09-08 (PyPI); commits daily.","one":"An open-source tool that builds a Slurm cluster on EC2 from a YAML file, with autoscaling compute queues.","what":"pcluster create-cluster provisions a head node running slurmctld, compute fleets that scale from zero, shared storage (FSx for Lustre, EFS) and EFA networking.","when":"Do-it-yourself Slurm on AWS.","avoid":"If you want AWS to handle node health and replacement: HyperPod.","verdict":"Mature and free; you run the cluster yourself.","src":[["aws/aws-parallelcluster","https://github.com/aws/aws-parallelcluster"]],"m":{"ver":"3.16.1","verDate":"2026-09-08","verSrc":"https://pypi.org/project/aws-parallelcluster/","first":"2018-11-10","nrel":86,"pypiLic":"Apache License 2.0","repo":"aws/aws-parallelcluster","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2014-05-12","stars":887,"commit":"2026-10-15","commitMsg":"Fix cluster update failing with `mount target already exists in this …","ghRel":"v3.16.1","ghRelDate":"2026-09-08","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"hyperpod","name":"Amazon SageMaker HyperPod","layer":"cloud","owner":"AWS","pypi":"sagemaker-hyperpod","status":"commercial","why":"Launched 2023-11-29 (re:Invent) with Slurm; Amazon EKS orchestration added (GA 2024-09-10); HyperPod CLI 3.11.0 on 2026-09-02 (PyPI).","one":"AWS's managed training clusters: Slurm or EKS on reserved GPU or Trainium instances, with health checks and automatic node replacement.","what":"Deep health checks at creation, agents that detect faulty nodes, replace them and resume jobs from the last checkpoint; Slurm or EKS as the orchestrator.","when":"Large reserved training clusters on AWS.","avoid":"Small, bursty or multi-cloud work.","verdict":"The managed 'resilient cluster' pattern; its health checks are the feature.","src":[["AWS News Blog: Introducing SageMaker HyperPod (2023-11-29)","https://aws.amazon.com/blogs/aws/introducing-amazon-sagemaker-hyperpod-a-purpose-built-infrastructure-for-distributed-training-at-scale/"],["AWS: EKS support in SageMaker HyperPod (2024-09)","https://aws.amazon.com/about-aws/whats-new/2024/09/amazon-eks-sagemaker-hyperpod-scale-foundation-model-development/"]],"m":{"ver":"3.11.0","verDate":"2026-09-02","verSrc":"https://pypi.org/project/sagemaker-hyperpod/","first":"2025-07-10","nrel":18,"pypiLic":"Apache-2.0","lic":"proprietary (AWS service); CLI Apache-2.0","last":"2026-09-02"}},{"id":"gke","name":"Google GKE and Cluster Toolkit","layer":"cloud","owner":"Google Cloud","repo":"GoogleCloudPlatform/cluster-toolkit","status":"commercial","why":"GKE is Google's managed Kubernetes (Kueue, JobSet and DRA supported); Cluster Toolkit v1.106.0 on 2026-10-13 deploys Slurm or GKE clusters for AI and HPC.","one":"Google's managed Kubernetes, plus an open-source toolkit (blueprints) for GPU and TPU clusters with Slurm or GKE.","what":"GKE node pools with GPUs or TPUs, compact placement, Kueue and JobSet (both largely developed by Google engineers); Cluster Toolkit blueprints build Slurm clusters with the Slurm-GCP integration.","when":"Training on Google Cloud, especially TPUs (see the JAX and TPU topic).","avoid":"","verdict":"Kubernetes-first; the cloud whose engineers wrote much of Kueue and JobSet.","src":[["GoogleCloudPlatform/cluster-toolkit","https://github.com/GoogleCloudPlatform/cluster-toolkit"],["GKE AI/ML docs","https://cloud.google.com/kubernetes-engine/docs/integrations/ai-infra"]],"m":{"repo":"GoogleCloudPlatform/cluster-toolkit","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2021-10-06","stars":367,"commit":"2026-10-13","commitMsg":"Release candidate v1.106.0 (#6453)","ghRel":"v1.106.0","ghRelDate":"2026-10-13","ver":"v1.106.0","verDate":"2026-10-13","verSrc":"https://github.com/GoogleCloudPlatform/cluster-toolkit/releases","lic":"GKE: proprietary (Google Cloud service); Cluster Toolkit Apache-2.0","last":"2026-10-13"}},{"id":"cyclecloud","name":"Azure CycleCloud (Slurm)","layer":"cloud","owner":"Microsoft Azure","repo":"Azure/cyclecloud-slurm","status":"active","why":"cyclecloud-slurm 4.0.11 on 2026-09-30.","one":"Azure's HPC cluster manager; its Slurm project creates autoscaling Slurm clusters on Azure VMs (Azure's managed Kubernetes for GPUs is AKS).","what":"CycleCloud provisions and autoscales nodes; cyclecloud-slurm wires Slurm's power-saving hooks to create and delete VMs; CycleCloud Workspace for Slurm packages it.","when":"Slurm on Azure.","avoid":"","verdict":"Azure's equivalent of ParallelCluster.","src":[["Azure/cyclecloud-slurm","https://github.com/Azure/cyclecloud-slurm"]],"m":{"repo":"Azure/cyclecloud-slurm","ghLic":"MIT","archived":false,"pushed":"2026-10-07","created":"2018-07-12","stars":84,"commit":"2026-09-30","commitMsg":"Use the runtime OS hostname instead of the bootstrap configuration va…","ghRel":"4.0.11","ghRelDate":"2026-09-30","ver":"4.0.11","verDate":"2026-09-30","verSrc":"https://github.com/Azure/cyclecloud-slurm/releases","lic":"CycleCloud: proprietary (Azure); cyclecloud-slurm MIT","last":"2026-09-30"}},{"id":"coreweave","name":"CoreWeave (CKS)","layer":"cloud","owner":"CoreWeave","status":"commercial","why":"GPU cloud (Nasdaq-listed since March 2025) offering CoreWeave Kubernetes Service and SUNK; bought Weights & Biases in May 2025.","one":"A GPU-specialised cloud ('neocloud') renting large NVIDIA clusters, managed through Kubernetes.","what":"CKS bare-metal Kubernetes with GPU nodes, InfiniBand, node health checks, SUNK for Slurm users, object and file storage.","when":"Renting thousands of GPUs with InfiniBand.","avoid":"","verdict":"Representative of the neoclouds; Kubernetes underneath, Slurm on top if you want it.","src":[["CoreWeave completes acquisition of Weights & Biases (2025-05-05)","https://www.coreweave.com/news/coreweave-completes-acquisition-of-weights-biases-2"]],"m":{"lic":"proprietary (service)","last":""}},{"id":"lambda","name":"Lambda (1-Click Clusters)","layer":"cloud","owner":"Lambda","status":"commercial","why":"GPU cloud selling on-demand instances and reserved multi-node clusters with InfiniBand.","one":"A GPU cloud whose 1-Click Clusters give you a ready multi-node NVIDIA cluster (optionally with Kubernetes or Slurm) for weeks or months.","what":"Reserved clusters of 16 to thousands of GPUs with InfiniBand and shared storage; you bring the scheduler or use the provided one.","when":"Short reserved training runs without a long cloud contract.","avoid":"","verdict":"Typical of renting a cluster rather than instances.","src":[["Lambda 1-Click Clusters","https://lambda.ai/1-click-clusters"]],"m":{"lic":"proprietary (service)","last":""}},{"id":"lustre","name":"Lustre","layer":"storage","owner":"OpenSFS community; DDN (Whamcloud) leads development","repo":"lustre/lustre-release","status":"active","why":"lustre.org lists 2.17.0 (2025-12-29) as the current major release, 2.15.8 (2025-12-03) as the current maintenance (LTS) release and 2.18.0 under development; development tags every few weeks (2.17.59 on 2026-09-28).","one":"The open-source parallel file system of supercomputers: one namespace, files striped over many storage servers, read and written by thousands of clients at once.","what":"Metadata servers (MDS/MDT) hold names and layouts; object storage servers (OSS/OST) hold the data stripes; clients talk to both directly. Fast for big sequential I/O such as checkpoints; weak on millions of tiny files. Managed versions: AWS FSx for Lustre, Google Managed Lustre, Azure Managed Lustre, DDN EXAScaler.","when":"Shared high-bandwidth storage for checkpoints and datasets on HPC and AI clusters.","avoid":"Many small files without packing them into shards.","verdict":"The default parallel file system; most clouds sell it managed.","src":[["lustre.org (current major and maintenance releases)","https://www.lustre.org/"],["lustre/lustre-release (mirror)","https://github.com/lustre/lustre-release"]],"m":{"repo":"lustre/lustre-release","ghLic":"NOASSERTION","archived":false,"pushed":"2026-10-13","created":"2020-06-06","stars":328,"commit":"2026-10-13","commitMsg":"LU-20782 osc: keep pages covered by another lock on cancel","ver":"2.17.0","verDate":"2025-12-29","verSrc":"https://www.lustre.org/lustre-2-17-0-released/","lic":"GPL-2.0 (COPYING)","last":"2026-10-13"}},{"id":"gpfs","name":"IBM Storage Scale (GPFS)","layer":"storage","owner":"IBM","status":"commercial","why":"IBM's commercial parallel file system, formerly GPFS and Spectrum Scale; no public repository.","one":"IBM's parallel file system (General Parallel File System), with distributed metadata and many enterprise features.","what":"Data and metadata spread across all servers, policy-based tiering to object storage or tape, used on IBM and other HPC systems.","when":"Sites that already license it.","avoid":"","verdict":"Lustre's commercial peer; you will meet it, rarely choose it.","src":[["IBM Storage Scale","https://www.ibm.com/products/storage-scale"]],"m":{"lic":"proprietary (IBM)","last":""}},{"id":"weka","name":"WEKA","layer":"storage","owner":"WEKA","status":"commercial","why":"Commercial software-defined parallel file system; no public repository.","one":"A software-defined parallel file system on NVMe flash, sold for AI training clusters, with tiering to object storage.","what":"Runs on servers with NVMe drives (or in the cloud), POSIX and S3 access, GPUDirect Storage support, strong small-file and metadata performance by vendor claims.","when":"High-performance shared storage for GPU clusters bought as a product.","avoid":"","verdict":"Popular with GPU clouds; performance figures are vendor claims unless independently measured.","src":[["WEKA","https://www.weka.io/"]],"m":{"lic":"proprietary","last":""}},{"id":"vast","name":"VAST Data","layer":"storage","owner":"VAST Data","status":"commercial","why":"Commercial all-flash storage platform; no public repository.","one":"All-flash storage with NFS, S3 and database interfaces, sold widely to GPU clouds and AI labs.","what":"Disaggregated design: stateless servers over shared NVMe enclosures; one namespace over NFS (with multipath and RDMA) and S3.","when":"Large AI clusters wanting one storage system for datasets and checkpoints.","avoid":"","verdict":"Common at neoclouds; judge it on independent numbers.","src":[["VAST Data","https://www.vastdata.com/"]],"m":{"lic":"proprietary","last":""}},{"id":"juicefs","name":"JuiceFS","layer":"storage","owner":"Juicedata","repo":"juicedata/juicefs","status":"active","why":"Community Edition v1.3.3 on 2026-08-07; commits daily.","one":"A POSIX file system whose data lives in object storage (S3, GCS, MinIO) and metadata in Redis, TiKV or a SQL database.","what":"Mount object storage as a file system with local caching; chunks files into blocks stored as objects; a Kubernetes CSI driver.","when":"Cheap shared file access to datasets in object storage, especially on Kubernetes.","avoid":"Checkpoint bursts that need parallel-file-system bandwidth without a warm cache.","verdict":"Good bridge from object storage to POSIX; performance depends on cache and metadata engine.","src":[["juicedata/juicefs","https://github.com/juicedata/juicefs"]],"m":{"repo":"juicedata/juicefs","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2021-01-08","stars":14540,"commit":"2026-10-15","commitMsg":"windows: fixed git clone panic. (#7696)","ghRel":"v1.3.3","ghRelDate":"2026-08-07","ver":"v1.3.3","verDate":"2026-08-07","verSrc":"https://github.com/juicedata/juicefs/releases","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"alluxio","name":"Alluxio","layer":"storage","owner":"Alluxio","repo":"Alluxio/alluxio","status":"maintained","why":"Open-source edition: the last GitHub release is v2.9.4 (2024-06-11, marked Latest); git tags v2.9.5 (2024-06-24) and v2.9.6 (2024-07-02) exist without a release (checked with the GitHub API 2026-10-16), so feeds that list tags show v2.9.6. Commits continue (2026-09-01); its README says it is 'purpose-built for analytics workloads'; the AI product (Alluxio Enterprise AI) is commercial.","one":"A distributed caching layer between compute and storage (formerly Tachyon, from UC Berkeley).","what":"Caches hot data from S3 or HDFS on local NVMe or RAM near compute, with a unified namespace.","when":"Analytics engines (Presto, Spark, Trino) over remote storage; AI data caching via the commercial edition.","avoid":"Expecting the open-source edition to target GPU training: its README points it at analytics.","verdict":"The open edition is analytics-focused and slow to release; treat the AI story as a commercial product.","src":[["Alluxio/alluxio README","https://github.com/Alluxio/alluxio"]],"m":{"repo":"Alluxio/alluxio","ghLic":"Apache-2.0","archived":false,"pushed":"2026-09-01","created":"2012-12-21","stars":7248,"commit":"2026-09-01","commitMsg":"Make S3 proxy reject unverified signatures by default","ghRel":"v2.9.6","ghRelDate":"2024-07-02","ver":"v2.9.4","verDate":"2024-06-11","verSrc":"https://github.com/Alluxio/alluxio/releases/tag/v2.9.4","lic":"Apache-2.0","last":"2026-09-01"}},{"id":"s3","name":"Object storage (Amazon S3, Google Cloud Storage)","layer":"storage","owner":"AWS, Google Cloud, others","status":"commercial","why":"The universal home of datasets and checkpoints; S3's API is the de facto standard.","one":"Key-value storage of immutable objects over HTTP: cheap, durable and nearly unlimited, but no POSIX file semantics and higher latency per request.","what":"PUT and GET whole objects (multipart for large ones); throughput scales with parallel requests. Training reads shards (WebDataset, MDS) from it and checkpoints are often written locally first, then uploaded.","when":"Datasets, checkpoint archives, anything shared across clusters or clouds.","avoid":"Many small random reads without sharding or a cache.","verdict":"Where data lives; the file systems above are caches or fast tiers in front of it.","src":[["Amazon S3 user guide","https://docs.aws.amazon.com/AmazonS3/latest/userguide/Welcome.html"]],"m":{"lic":"proprietary services","last":""}},{"id":"minio","name":"MinIO (open-source server)","layer":"storage","owner":"MinIO","repo":"minio/minio","status":"archived","why":"The minio/minio repository is archived and its README says 'THIS REPOSITORY IS NO LONGER MAINTAINED', pointing to the AIStor Free and AIStor Enterprise editions; the last push was 2026-04-24. It went to maintenance mode in December 2025 after binary releases had stopped.","one":"The best-known self-hosted S3-compatible object store, used everywhere as local S3 for development and on-prem clusters.","what":"One Go binary serving the S3 API over local disks, with erasure coding when distributed. Existing container images still run; there will be no new open-source releases or fixes from MinIO.","when":"Local S3 for experiments with an existing image (as this topic's Storage lab may), knowing it is frozen.","avoid":"New production deployments of the open-source server: consider AIStor (MinIO's commercial line), Ceph RGW, SeaweedFS or Garage.","verdict":"A cautionary tale: an AGPL project whose company moved its users to a commercial edition and archived the repository.","src":[["minio/minio README (archived)","https://github.com/minio/minio"],["InfoQ: MinIO maintenance mode and S3 API alternatives (2025-12)","https://www.infoq.com/news/2025/12/minio-s3-api-alternatives/"]],"m":{"repo":"minio/minio","ghLic":"AGPL-3.0","archived":true,"pushed":"2026-04-24","created":"2015-01-14","stars":61318,"commit":"2026-02-12","commitMsg":"update README.md format and clarify state of the project","lic":"AGPL-3.0","last":"2026-02-12"}},{"id":"dcgm","name":"NVIDIA DCGM and dcgmi","layer":"obs","owner":"NVIDIA","repo":"NVIDIA/DCGM","status":"active","why":"DCGM 4.6.1 on 2026-08-19 (GitHub release).","one":"NVIDIA's Data Center GPU Manager: a host engine that collects GPU health and performance counters, and dcgmi, its command line.","what":"Field IDs for utilisation, SM activity, tensor-core activity, memory bandwidth, NVLink and PCIe traffic, ECC and XID errors; dcgmi diag runs active health checks (levels 1 to 4) used before admitting a node; dcgmi health watches for faults.","when":"Node health checks before and between jobs, and the source of real GPU metrics.","avoid":"Judging efficiency from nvidia-smi's 'GPU-Util' alone (it only says a kernel was running); use DCGM's SM activity and tensor activity.","verdict":"The ground truth for GPU health; dcgmi diag belongs in every prolog or node-validation script.","src":[["NVIDIA/DCGM","https://github.com/NVIDIA/DCGM"],["DCGM user guide","https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/index.html"]],"m":{"repo":"NVIDIA/DCGM","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2020-12-15","stars":800,"commit":"2026-08-19","commitMsg":"DCGM 4.6.1 (#309)","ghRel":"v4.6.1","ghRelDate":"2026-08-19","ver":"v4.6.1","verDate":"2026-08-19","verSrc":"https://github.com/NVIDIA/DCGM/releases","lic":"Apache-2.0","last":"2026-08-19"}},{"id":"dcgmexp","name":"DCGM exporter","layer":"obs","owner":"NVIDIA","repo":"NVIDIA/dcgm-exporter","status":"active","why":"4.8.4 on 2026-09-18.","one":"Exposes DCGM metrics as a Prometheus endpoint, one per node (a DaemonSet on Kubernetes, installed by the GPU Operator).","what":"Metrics such as DCGM_FI_DEV_GPU_UTIL, DCGM_FI_PROF_SM_ACTIVE (named DCGM_FI_PROF_SM_UTIL_RATIO since DCGM 4.6.1, the old name kept as an alias; commented out in the default counters), DCGM_FI_PROF_PIPE_TENSOR_ACTIVE, DCGM_FI_DEV_FB_USED and XID errors, labelled with the pod or Slurm job using the GPU.","when":"Any GPU cluster with Prometheus.","avoid":"","verdict":"The standard way GPU metrics reach dashboards.","src":[["NVIDIA/dcgm-exporter","https://github.com/NVIDIA/dcgm-exporter"]],"m":{"repo":"NVIDIA/dcgm-exporter","ghLic":"Apache-2.0","archived":false,"pushed":"2026-09-18","created":"2021-08-11","stars":1904,"commit":"2026-09-18","commitMsg":"feat: release DCGM-Exporter 4.8.4 (#745)","ghRel":"4.8.4","ghRelDate":"2026-09-18","ver":"4.8.4","verDate":"2026-09-18","verSrc":"https://github.com/NVIDIA/dcgm-exporter/releases","lic":"Apache-2.0","last":"2026-09-18"}},{"id":"prom","name":"Prometheus","layer":"obs","owner":"CNCF (graduated)","repo":"prometheus/prometheus","status":"active","why":"Latest release 3.15.0 (2026-09-25, GitHub's Latest); 3.13.4 (published 2026-10-02) is a patch to an older line, and is the version the Observability and cost child page ran. Commits daily.","one":"The metrics database of cloud-native systems: scrapes numeric time series from endpoints and answers PromQL queries and alerts.","what":"Pull model: every N seconds it scrapes /metrics from exporters (DCGM exporter, node exporter, kube-state-metrics, Slurm exporters, or Slurm 25.11+ itself: slurmctld serves OpenMetrics with MetricsType=metrics/openmetrics) and stores time series; alert rules fire through Alertmanager.","when":"Cluster and job metrics, alerting on GPU errors, stalled jobs, low utilisation.","avoid":"Per-step training metrics such as loss (use an experiment tracker).","verdict":"Default choice; pair with Grafana.","src":[["prometheus/prometheus","https://github.com/prometheus/prometheus"]],"m":{"repo":"prometheus/prometheus","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-16","created":"2012-11-24","stars":66578,"commit":"2026-10-15","commitMsg":"otlp: count only out-of-order exemplars in the out-of-order counter (…","ghRel":"3.13.4","ghRelDate":"2026-10-02","ver":"3.15.0","verDate":"2026-09-25","verSrc":"https://github.com/prometheus/prometheus/releases/tag/v3.15.0","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"grafana","name":"Grafana","layer":"obs","owner":"Grafana Labs","repo":"grafana/grafana","status":"active","why":"13.2.4 on 2026-10-13; licence AGPL-3.0 since 2021.","one":"Dashboards over Prometheus and other data sources.","what":"Panels of PromQL queries; NVIDIA publishes a DCGM dashboard; alerting and annotations (mark a job start or failure on a graph).","when":"Every cluster dashboard.","avoid":"","verdict":"Default dashboarding; mind the AGPL licence if you modify and serve it.","src":[["grafana/grafana","https://github.com/grafana/grafana"]],"m":{"repo":"grafana/grafana","ghLic":"AGPL-3.0","archived":false,"pushed":"2026-10-16","created":"2013-12-11","stars":77297,"commit":"2026-10-16","commitMsg":"I18n: Download translations from Crowdin (#135131)","ghRel":"13.2.4","ghRelDate":"2026-10-13","ver":"13.2.4","verDate":"2026-10-13","verSrc":"https://github.com/grafana/grafana/releases","lic":"AGPL-3.0","last":"2026-10-16"}},{"id":"airflow","name":"Apache Airflow","layer":"flow","owner":"Apache Software Foundation","repo":"apache/airflow","pypi":"apache-airflow","status":"active","why":"3.3.2 on 2026-09-17 (PyPI); Airflow 3.0 shipped 2025-04-22.","one":"The most used workflow scheduler: DAGs of tasks written in Python, run on a schedule or on events.","what":"A scheduler decides which tasks are ready, executors (Celery, Kubernetes, Edge) run them; Airflow 3 added a Task Execution API, DAG versioning and the airflow.sdk authoring namespace.","when":"Data pipelines feeding training (ingest, filter, tokenise), scheduled evaluation and retraining.","avoid":"As the launcher of a multi-node training job: have a task submit to Slurm, Kubernetes or Ray.","verdict":"The safe default for data and ML pipelines; it orchestrates, it does not train.","src":[["Airflow 3.0.0 release notes","https://airflow.apache.org/docs/apache-airflow/3.0.0/release_notes.html"],["apache/airflow","https://github.com/apache/airflow"]],"m":{"ver":"3.3.2","verDate":"2026-09-17","verSrc":"https://pypi.org/project/apache-airflow/","first":"2017-05-09","nrel":301,"pypiLic":"Apache-2.0","repo":"apache/airflow","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2015-04-13","stars":47186,"commit":"2026-10-16","commitMsg":"Fingerprint durable agent steps that hold sets or values that are not…","lic":"Apache-2.0","last":"2026-10-16"}},{"id":"kfp","name":"Kubeflow Pipelines","layer":"flow","owner":"Kubeflow (CNCF)","repo":"kubeflow/pipelines","pypi":"kfp","status":"active","why":"kfp 2.17.0 on 2026-07-09 (PyPI); backend 2.17.2 on 2026-09-04.","one":"ML pipelines on Kubernetes: each step a container, the graph compiled to an intermediate representation and run by a backend (Argo Workflows).","what":"@dsl.component and @dsl.pipeline in Python compile to YAML; artifacts and metadata tracked; Vertex AI Pipelines runs the same format.","when":"Kubernetes shops wanting containerised ML pipelines; Google Cloud Vertex users.","avoid":"Small teams without Kubernetes.","verdict":"Solid inside the Kubeflow world; heavier than Metaflow or Prefect.","src":[["kubeflow/pipelines","https://github.com/kubeflow/pipelines"]],"m":{"ver":"2.17.0","verDate":"2026-07-09","verSrc":"https://pypi.org/project/kfp/","first":"2019-03-06","nrel":155,"pypiLic":"Apache Software License","repo":"kubeflow/pipelines","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2018-05-12","stars":4242,"commit":"2026-10-15","commitMsg":"chore(deps): bump react-dropzone in /frontend (#14908)","ghRel":"2.17.2","ghRelDate":"2026-09-04","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"flyte","name":"Flyte","layer":"flow","owner":"Linux Foundation AI & Data (Union.ai leads)","repo":"flyteorg/flyte","pypi":"flyte","status":"active","why":"Flyte 2 SDK (flyte 2.11.4 on 2026-10-14; 2.0.0 on 2026-02-18) beside Flyte 1 (flytekit 1.16.29); Union's docs said Flyte 2 distributed execution was 'coming to open source soon'.","one":"Strongly typed, versioned, containerised workflows on Kubernetes, born at Lyft.","what":"Tasks and workflows in Python with typed inputs and outputs, caching, retries, and plugins for PyTorch, Ray and Spark jobs. Flyte 2 makes workflows dynamic Python with durable execution.","when":"ML teams on Kubernetes wanting reproducible, typed pipelines.","avoid":"","verdict":"Strong design; check which parts of Flyte 2 are open source when you adopt it.","src":[["flyteorg/flyte","https://github.com/flyteorg/flyte"],["Flyte 2 SDK packages (Union docs)","https://www.union.ai/docs/v2/flyte/api-reference/flyte-sdk/packages"]],"m":{"ver":"2.11.4","verDate":"2026-10-14","verSrc":"https://pypi.org/project/flyte/","first":"2025-03-14","nrel":200,"pypiLic":"","repo":"flyteorg/flyte","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2019-10-21","stars":7705,"commit":"2026-10-16","commitMsg":"storage: bump stow to v0.5.1 to stream S3 uploads of files instead of…","ghRel":"v2.0.51","ghRelDate":"2026-10-08","lic":"Apache-2.0","last":"2026-10-16"}},{"id":"metaflow","name":"Metaflow","layer":"flow","owner":"Netflix (Outerbounds sells the managed version)","repo":"Netflix/metaflow","pypi":"metaflow","status":"active","why":"2.19.39 on 2026-09-02 (PyPI).","one":"A Python library for data-science workflows, from laptop to cloud, built at Netflix.","what":"FlowSpec classes with @step methods; @resources(gpu=1) and @kubernetes or @batch send a step to the cloud; artifacts versioned automatically; deploys to Argo, Step Functions or Airflow.","when":"Data scientists who want to stay in Python and scale steps out.","avoid":"","verdict":"The friendliest of the workflow tools for ML scientists.","src":[["Netflix/metaflow","https://github.com/Netflix/metaflow"]],"m":{"ver":"2.19.39","verDate":"2026-09-02","verSrc":"https://pypi.org/project/metaflow/","first":"2019-12-03","nrel":267,"pypiLic":"Apache Software License","repo":"Netflix/metaflow","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-12","created":"2019-09-17","stars":10304,"commit":"2026-10-06","commitMsg":"fix: pin devstack to a legacy minio (#3400)","ghRel":"2.19.39","ghRelDate":"2026-09-02","lic":"Apache-2.0","last":"2026-10-06"}},{"id":"prefect","name":"Prefect","layer":"flow","owner":"Prefect","repo":"PrefectHQ/prefect","pypi":"prefect","status":"active","why":"3.8.8 on 2026-10-06 (PyPI); Prefect 3.0 on 2024-09-03.","one":"Python-native workflow orchestration: decorate functions with @flow and @task.","what":"Any Python function becomes a tracked, retryable task; work pools run flows on Kubernetes, Docker or serverless; a prefect-ray integration runs tasks on Ray.","when":"Python-first teams that find Airflow heavy.","avoid":"","verdict":"Good general-purpose choice; not ML-specific.","src":[["PrefectHQ/prefect","https://github.com/PrefectHQ/prefect"]],"m":{"ver":"3.8.8","verDate":"2026-10-06","verSrc":"https://pypi.org/project/prefect/","first":"2019-03-24","nrel":899,"pypiLic":"Apache-2.0","repo":"PrefectHQ/prefect","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2018-06-29","stars":24025,"commit":"2026-10-15","commitMsg":"fix: Replace dead Sanity logo URLs in bundled collection metadata (#2…","ghRel":"3.8.8","ghRelDate":"2026-10-06","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"dagster","name":"Dagster","layer":"flow","owner":"Dagster Labs","repo":"dagster-io/dagster","pypi":"dagster","status":"active","why":"1.13.26 on 2026-10-09 (PyPI).","one":"Data orchestration around assets (tables, files, models) rather than tasks.","what":"You declare software-defined assets and their dependencies; Dagster materialises them, tracks lineage and freshness.","when":"Data platforms where datasets and models are the things to keep fresh.","avoid":"","verdict":"Best for data lineage; a fit for dataset pipelines feeding training.","src":[["dagster-io/dagster","https://github.com/dagster-io/dagster"]],"m":{"ver":"1.13.26","verDate":"2026-10-09","verSrc":"https://pypi.org/project/dagster/","first":"2018-06-12","nrel":746,"pypiLic":"Apache-2.0","repo":"dagster-io/dagster","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-12","created":"2018-04-30","stars":16282,"commit":"2026-10-12","commitMsg":"DUX-30: Mobile variant of the run list page (#27223)","ghRel":"1.13.26","ghRelDate":"2026-10-09","lic":"Apache-2.0","last":"2026-10-12"}},{"id":"zenml","name":"ZenML","layer":"flow","owner":"ZenML","repo":"zenml-io/zenml","pypi":"zenml","status":"active","why":"0.98.0 on 2026-10-14 (PyPI).","one":"An MLOps framework that puts one pipeline API over pluggable stacks (orchestrator, artifact store, tracker, registry).","what":"Write a pipeline once; switch the stack from local to Kubeflow, Airflow, SageMaker or Vertex; integrates MLflow, W&B and others.","when":"Teams wanting portability across MLOps tools.","avoid":"","verdict":"A glue layer; adds a dependency for portability you may not need.","src":[["zenml-io/zenml","https://github.com/zenml-io/zenml"]],"m":{"ver":"0.98.0","verDate":"2026-10-14","verSrc":"https://pypi.org/project/zenml/","first":"2020-12-13","nrel":198,"pypiLic":"Apache-2.0","repo":"zenml-io/zenml","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-15","created":"2020-11-19","stars":5616,"commit":"2026-10-14","commitMsg":"Add version 0.97.0 to legacy docs (#5356) (#5359)","ghRel":"0.98.0","ghRelDate":"2026-10-14","lic":"Apache-2.0","last":"2026-10-14"}},{"id":"mlflow","name":"MLflow","layer":"track","owner":"Linux Foundation (Databricks leads)","repo":"mlflow/mlflow","pypi":"mlflow","status":"active","why":"3.17.1 on 2026-10-13 (PyPI); MLflow 3.0 on 2025-06-10.","one":"Open-source experiment tracking, model registry and (since 3.x) GenAI tracing and evaluation.","what":"mlflow.log_metric and log_artifact to a tracking server; the Model Registry versions models with aliases (champion, challenger); self-hostable on any database plus object storage.","when":"A self-hosted tracker and registry; Databricks users.","avoid":"","verdict":"The open default for tracking and registry.","src":[["mlflow/mlflow","https://github.com/mlflow/mlflow"]],"m":{"ver":"3.17.1","verDate":"2026-10-13","verSrc":"https://pypi.org/project/mlflow/","first":"2018-06-04","nrel":191,"pypiLic":"Copyright 2018 Databricks, Inc.  All rights reserved.","repo":"mlflow/mlflow","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-16","created":"2018-06-05","stars":28401,"commit":"2026-10-15","commitMsg":"Fix `search_traces` ordering by `end_time` in the SQL store (#26761)","ghRel":"3.17.1","ghRelDate":"2026-10-13","lic":"Apache-2.0","last":"2026-10-15"}},{"id":"wandb","name":"Weights & Biases","layer":"track","owner":"CoreWeave (since 2025-05-05)","repo":"wandb/wandb","pypi":"wandb","status":"active","why":"Client 0.30.0 on 2026-09-09 (PyPI); CoreWeave completed the acquisition on 2025-05-05.","one":"The most used hosted experiment tracker for deep learning, plus artifacts, a registry, sweeps and Weave for LLM apps.","what":"wandb.init and wandb.log stream metrics, system metrics (GPU utilisation) and artifacts to a hosted or self-managed server; a Registry for models and datasets.","when":"Training runs where you want rich dashboards with little setup.","avoid":"Air-gapped sites without a self-managed licence.","verdict":"Market leader for training runs; now owned by a GPU cloud.","src":[["CoreWeave completes acquisition of W&B (2025-05-05)","https://www.coreweave.com/news/coreweave-completes-acquisition-of-weights-biases-2"],["wandb/wandb","https://github.com/wandb/wandb"]],"m":{"ver":"0.30.0","verDate":"2026-09-09","verSrc":"https://pypi.org/project/wandb/","first":"2017-03-24","nrel":335,"pypiLic":"MIT License","repo":"wandb/wandb","ghLic":"MIT","archived":false,"pushed":"2026-10-16","created":"2017-03-24","stars":11300,"commit":"2026-10-15","commitMsg":"chore(sdk): default EvalTable back to the Weave backend (#13172)","ghRel":"v0.30.0","ghRelDate":"2026-09-09","lic":"MIT (client); the server is a commercial service","last":"2026-10-15"}},{"id":"neptune","name":"Neptune","layer":"track","owner":"neptune.ai (acquired by OpenAI, announced December 2025)","repo":"neptune-ai/neptune-client","pypi":"neptune","status":"archived","why":"OpenAI agreed to buy neptune.ai in December 2025; the hosted app and API were turned off in early March 2026 (Neptune's transition hub: 2026-03-05 10 am PST, moved from March 4 on 2025-12-05) and hosted data deleted; the client repository is archived (last release 1.14.0.post2 on 2026-03-17).","one":"A hosted experiment tracker known for handling very many runs and metrics (foundation-model training).","what":"Was: neptune.init_run and logging of metrics, files and system metrics to a hosted server. The service no longer exists.","when":"Never for new work; migrate old runs' exports.","avoid":"Everything: the service is shut down.","verdict":"Dead as a product; the cleanest recent example of tracker lock-in risk.","src":[["Neptune transition hub","https://docs.neptune.ai/transition_hub"],["InfoWorld: OpenAI to acquire Neptune (2025-12-04)","https://www.infoworld.com/article/4101200/openai-to-acquire-a-training-tracker-neptune.html"],["neptune-ai/neptune-client (archived)","https://github.com/neptune-ai/neptune-client"]],"m":{"ver":"1.14.0.post2","verDate":"2026-03-17","verSrc":"https://pypi.org/project/neptune/","first":"2023-02-23","nrel":74,"pypiLic":"Apache-2.0","repo":"neptune-ai/neptune-client","ghLic":"Apache-2.0","archived":true,"pushed":"2026-03-17","created":"2019-02-11","stars":623,"commit":"2025-06-09","commitMsg":"Merge pull request #1919 from neptune-ai/normandy7-patch-1","ghRel":"1.14.0.post2","ghRelDate":"2026-03-17","lic":"Apache-2.0","last":"2026-03-17"}},{"id":"clearml","name":"ClearML","layer":"track","owner":"ClearML","repo":"clearml/clearml","pypi":"clearml","status":"active","why":"2.1.12 on 2026-08-19 (PyPI).","one":"Open-source MLOps suite: experiment tracking, data versioning, pipelines and an agent that runs queued jobs on GPU machines.","what":"Two lines of code capture runs automatically; clearml-agent pulls jobs from queues onto workers; a self-hosted server.","when":"Self-hosted all-in-one tracking plus job queues for small GPU fleets.","avoid":"","verdict":"Capable self-hosted alternative to W&B plus a light scheduler.","src":[["clearml/clearml","https://github.com/clearml/clearml"]],"m":{"ver":"2.1.12","verDate":"2026-08-19","verSrc":"https://pypi.org/project/clearml/","first":"2020-12-22","nrel":200,"pypiLic":"Apache License 2.0","repo":"clearml/clearml","ghLic":"Apache-2.0","archived":false,"pushed":"2026-10-12","created":"2019-06-10","stars":6908,"commit":"2026-10-12","commitMsg":"Feat/abstractproperty decorator (#1711)","ghRel":"v2.1.12","ghRelDate":"2026-08-19","lic":"Apache-2.0","last":"2026-10-12"}},{"id":"registry","name":"Model registries (MLflow, W&B, Hugging Face Hub, cloud registries)","layer":"track","owner":"various","status":"commercial","why":"A function rather than one product: MLflow Model Registry, W&B Registry, the Hugging Face Hub, SageMaker and Vertex AI model registries.","one":"Where trained models are stored with versions, metadata and stage labels so serving and evaluation pick the right one.","what":"Each version links to the run, data and code that produced it; aliases or stages (staging, production) gate deployment; access control and lineage.","when":"As soon as more than one person deploys models.","avoid":"Using a bucket path naming scheme as a registry.","verdict":"Pick the registry of the tracker you already use.","src":[["MLflow Model Registry docs","https://mlflow.org/docs/latest/ml/model-registry/"]],"m":{"lic":"various","last":""}}],"lineage":[["trainerv1","trainer","doc","2025-07","Trainer v2 (TrainJob) released; v1 kept on the release-1.9 branch, Kueue calls v1 legacy","https://github.com/kubeflow/trainer"],["runai","kai","doc","2025-04","NVIDIA open-sources the Run:ai scheduler as KAI Scheduler","https://developer.nvidia.com/blog/nvidia-open-sources-runai-scheduler-to-foster-community-collaboration/"],["trainer","jobset","doc","2025-07","every TrainJob is run as a JobSet","https://developers.redhat.com/articles/2026/09/29/distributed-training-openshift-ai-34-kubeflow-trainer-v2"],["slurm","slinky","doc","2024-11","SchedMD open-sources Slinky (Slurm on Kubernetes)","https://slurm.schedmd.com/slinky.html"],["minio","s3","practice","2025-12","MinIO open-source server to maintenance mode, then archived; users move to AIStor or other S3-compatible stores","https://www.infoq.com/news/2025/12/minio-s3-api-alternatives/"],["neptune","mlflow","practice","2026-03","Neptune hosted service shut down; users export runs to another tracker","https://www.infoworld.com/article/4101200/openai-to-acquire-a-training-tracker-neptune.html"]],"own":[["determined","2021-06","HPE","HPE acquires Determined AI","https://www.hpe.com/us/en/newsroom/press-release/2021/06/hewlett-packard-enterprise-acquires-determined-ai-to-accelerate-artificial-intelligence-innovation-with-fast-and-simple-machine-learning-modeling.html"],["runai","2024-12","NVIDIA","NVIDIA completes the Run:ai acquisition (2024-12-30)","https://techcrunch.com/2024/12/30/nvidia-completes-acquisition-of-ai-infrastructure-startup-runai/"],["deepspeedl","2025-02","LF AI & Data","Microsoft contributes DeepSpeed to LF AI & Data","https://lfaidata.foundation/blog/2025/02/03/lf-ai-data-welcomes-deepspeed-advancing-deep-learning-optimization/"],["nomad","2025-02","IBM","IBM completes the HashiCorp acquisition (2025-02-27)","https://www.techrepublic.com/article/ibm-hashicorp-acquisition-completed/"],["openpbs","2025-03","Siemens","Siemens completes the Altair acquisition (2025-03-26)","https://www.nafems.org/about-us/media/news/industrynews1003/siemens-completes-10-billion-acquisition-of-altair-engineering/"],["wandb","2025-05","CoreWeave","CoreWeave completes the W&B acquisition (2025-05-05)","https://www.coreweave.com/news/coreweave-completes-acquisition-of-weights-biases-2"],["ray","2025-10","PyTorch Foundation","Ray becomes a PyTorch Foundation project (2025-10-22)","https://pytorch.org/blog/pytorch-foundation-welcomes-ray-to-deliver-a-unified-open-source-ai-compute-stack/"],["neptune","2025-12","OpenAI","OpenAI agrees to acquire neptune.ai; service shut down March 2026","https://www.infoworld.com/article/4101200/openai-to-acquire-a-training-tracker-neptune.html"],["slurm","2025-12","NVIDIA","NVIDIA acquires SchedMD (2025-12-15)","https://blogs.nvidia.com/blog/nvidia-acquires-schedmd/"]],"lin":[{"id":"mpiop","g":"Kubernetes training APIs","s":"2018-05","sn":"repository created","e":"2026-10"},{"id":"trainerv1","g":"Kubernetes training APIs","s":"2017-06","sn":"repository created","e":"2026-10"},{"id":"trainer","g":"Kubernetes training APIs","s":"2025-07","sn":"v2.0 release","e":"2026-10"},{"id":"jobset","g":"Kubernetes training APIs","s":"2023-03","sn":"repository created","e":"2026-10"},{"id":"kueue","g":"Kubernetes training APIs","s":"2022-02","sn":"repository created","e":"2026-10"},{"id":"volcano","g":"Kubernetes training APIs","s":"2019-03","sn":"repository created","e":"2026-10"},{"id":"kai","g":"Kubernetes training APIs","s":"2025-02","sn":"repository created","e":"2026-10"},{"id":"runai","g":"Kubernetes training APIs","s":"2024-12","sn":"as an NVIDIA product (acquisition closed 2024-12-30); the company is older","e":"2026-10"},{"id":"openpbs","g":"Slurm and clusters","s":"2016-05","sn":"repository created","e":"2026-04"},{"id":"slurm","g":"Slurm and clusters","s":"2002","sn":"initial release 2002 (Slurm FAQ, slurm.schedmd.com/faq.html)","e":"2026-10"},{"id":"slinky","g":"Slurm and clusters","s":"2024-11","sn":"open-source release","e":"2026-10"},{"id":"sunk","g":"Slurm and clusters","s":"2023-03","sn":"CoreWeave release notes, March 2023","e":"2026-10"},{"id":"hyperpod","g":"Slurm and clusters","s":"2023-11","sn":"launch post, 2023-11-29","e":"2026-10"},{"id":"pcluster","g":"Slurm and clusters","s":"2014-05","sn":"repository created","e":"2026-10"},{"id":"ray","g":"Runtimes and platforms","s":"2016-10","sn":"repository created","e":"2026-10"},{"id":"kuberay","g":"Runtimes and platforms","s":"2020-10","sn":"repository created","e":"2026-10"},{"id":"skypilot","g":"Runtimes and platforms","s":"2021-08","sn":"repository created","e":"2026-10"},{"id":"determined","g":"Runtimes and platforms","s":"2020-04","sn":"repository created","e":"2025-03"},{"id":"nomad","g":"Runtimes and platforms","s":"2015-06","sn":"repository created","e":"2026-10"},{"id":"minio","g":"Storage","s":"2015-01","sn":"repository created","e":"2026-02"},{"id":"juicefs","g":"Storage","s":"2021-01","sn":"repository created","e":"2026-10"},{"id":"alluxio","g":"Storage","s":"2012-12","sn":"repository created","e":"2026-10"},{"id":"neptune","g":"Tracking","s":"2019-02","sn":"repository created","e":"2026-03"},{"id":"wandb","g":"Tracking","s":"2017-03","sn":"first PyPI release","e":"2026-10"},{"id":"mlflow","g":"Tracking","s":"2018-06","sn":"first PyPI release","e":"2026-10"},{"id":"clearml","g":"Tracking","s":"2019-06","sn":"repository created","e":"2026-10"}],"hw":[["onprem","Own GPU cluster, small or no platform team"],["k8s","Company Kubernetes platform"],["cloud","Renting cloud or neocloud GPUs"],["laptop","One machine (laptop or workstation)"]],"pick":[{"id":"pretrain","label":"Run multi-node pretraining (hundreds of GPUs, weeks)","stack":["slurm","torchrun","lustre","dcgm","wandb"],"avoid":["determined","nomad"],"why":"Long synchronous jobs want whole nodes, gang allocation, topology-aware placement, fast checkpoint storage and node health checks between restarts. The Failure lab covers restarts.","hw":{"onprem":"Slurm with a parallel file system (Lustre or a vendor system) and a dcgmi diag prolog.","k8s":"JobSet or TrainJob admitted by Kueue with topology-aware scheduling, or Slinky if researchers want sbatch.","cloud":"A managed resilient cluster (HyperPod, GKE with Kueue, CoreWeave with SUNK) rather than loose VMs.","laptop":"Not this job: rehearse the launch with 2 to 4 CPU processes (the running example) and rent the cluster."}},{"id":"share","label":"Share one GPU cluster between teams with quotas","stack":["kueue","kai","slurm"],"avoid":["k8s"],"why":"Sharing needs queues, quotas, borrowing of idle capacity, fair share and preemption. Slurm has these built in (partitions, QOS, fairshare); on Kubernetes the default scheduler has none, so add Kueue (keeps the default scheduler) or KAI or Volcano (replace it).","hw":{"onprem":"Slurm accounts, QOS and fairshare via slurmdbd.","k8s":"Kueue ClusterQueues per team in a cohort, with borrowing and preemption.","cloud":"Same as Kubernetes, plus a cost cap per team.","laptop":"Not applicable; the Scheduling lab simulates it."}},{"id":"sweep","label":"Run many small experiments and sweeps","stack":["submitit","skypilot","ray","wandb"],"avoid":["trainerv1"],"why":"Hundreds of one-GPU jobs need cheap submission and tracking more than gang scheduling: submitit on Slurm, Ray Tune inside a Ray cluster, or SkyPilot on rented GPUs, with every run logged to a tracker.","hw":{"onprem":"submitit job arrays on Slurm.","k8s":"Kueue-admitted Jobs or Ray Tune on KubeRay.","cloud":"SkyPilot managed jobs on spot instances.","laptop":"Ray Tune or a plain loop, logging to MLflow."}},{"id":"rl","label":"RL and post-training with many cooperating processes","stack":["ray","kuberay","torchrun"],"avoid":[],"src":[["veRL README","https://github.com/volcengine/verl"],["OpenRLHF README","https://github.com/OpenRLHF/OpenRLHF"]],"why":"Generation workers, reward models, trainers and a weight-sync loop are heterogeneous long-lived processes; Ray actors and placement groups express that directly, which is why open RL frameworks such as veRL and OpenRLHF are built on Ray (their READMEs).","hw":{"onprem":"A Ray cluster started inside a Slurm allocation.","k8s":"KubeRay RayJob admitted by Kueue.","cloud":"KubeRay on managed Kubernetes or SkyPilot.","laptop":"Local Ray with --num-cpus 4 (the Launch lab's Ray run)."}},{"id":"launch","label":"Start the processes of one multi-node job","stack":["torchrun","jobset","accelerate"],"avoid":["pdsh"],"why":"Something must start one process per GPU on every node and tell each its rank and the rendezvous address. torchrun does it for PyTorch; the scheduler supplies the address (SLURM_* variables, JobSet's headless service, Ray's worker group). The Launch lab compares the three.","hw":{"onprem":"srun torchrun ... with MASTER_ADDR from the first host of SLURM_NODELIST.","k8s":"JobSet (or TrainJob) with torchrun pointing at the headless service name.","cloud":"SkyPilot or the cluster's scheduler sets the node list; still torchrun.","laptop":"torchrun --nproc-per-node 4 with the gloo backend."}},{"id":"store","label":"Store datasets and checkpoints","stack":["s3","lustre","juicefs"],"avoid":["minio","alluxio"],"why":"Datasets and archived checkpoints live in object storage; a parallel file system or local NVMe absorbs the checkpoint burst; JuiceFS-style layers give POSIX over object storage. The Storage lab measures the trade-offs.","hw":{"onprem":"Lustre (or a vendor parallel file system) plus an object store.","k8s":"Object storage plus a CSI-mounted file system (managed Lustre, JuiceFS).","cloud":"S3 or GCS plus the provider's managed Lustre for checkpoints.","laptop":"Local disk; an existing MinIO image only for S3-API experiments (the server is archived)."}},{"id":"observe","label":"Watch GPU health and utilisation","stack":["dcgm","dcgmexp","prom","grafana"],"avoid":[],"why":"Health checks (dcgmi diag) catch bad nodes before a job lands on them; DCGM metrics scraped by Prometheus show real SM and tensor activity per job, which nvidia-smi's utilisation does not. The Cost lab explains the difference.","hw":{"onprem":"DCGM exporter on every node, Prometheus, Grafana, dcgmi diag in the Slurm prolog or a health-check script.","k8s":"GPU Operator installs the exporter; the NVIDIA DCGM dashboard in Grafana.","cloud":"Provider health agents plus your own DCGM exporter.","laptop":"No NVIDIA GPU here: read the metric definitions."}},{"id":"track","label":"Track experiments and register models","stack":["wandb","mlflow","registry"],"avoid":["neptune","determined"],"why":"Every run's config, metrics and checkpoints must be findable later; a registry gives versions and aliases for what gets deployed. Hosted W&B or self-hosted MLflow are the common choices; Neptune's shutdown shows why exports matter.","hw":{"onprem":"Self-hosted MLflow (or W&B self-managed) on a database plus object storage.","k8s":"MLflow on the cluster or hosted W&B.","cloud":"Hosted W&B or the cloud's managed MLflow.","laptop":"Local MLflow (a file store)."}},{"id":"pipe","label":"Schedule data, training and evaluation pipelines","stack":["airflow","flyte","metaflow","kfp"],"avoid":[],"why":"A workflow tool runs the steps around training on a schedule (ingest, filter, tokenise, train, evaluate, register) and submits the heavy steps to Slurm, Kubernetes or Ray. Pick by where you run and who writes the pipelines.","hw":{"onprem":"Airflow submitting sbatch jobs.","k8s":"Flyte, Kubeflow Pipelines or Argo; Airflow with the KubernetesExecutor.","cloud":"The cloud's managed Airflow or Vertex Pipelines; Metaflow on AWS.","laptop":"Prefect or Metaflow locally."}},{"id":"slurmk8s","label":"Give researchers sbatch on a Kubernetes platform","stack":["slinky","sunk","k8s"],"avoid":[],"why":"Researchers want sbatch and srun; the platform team wants one Kubernetes estate. Slinky (open source) and SUNK (CoreWeave) run Slurm's daemons as pods so both share the GPUs.","hw":{"onprem":"Usually unnecessary: plain Slurm.","k8s":"Slinky's slurm-operator.","cloud":"CoreWeave SUNK, or Slinky on GKE or EKS.","laptop":"Not applicable."}}],"slots":[["k8strain","Multi-node PyTorch job on Kubernetes","PyTorchJob (Training Operator v1)","trainerv1"],["k8sgpu","GPU quotas and fractions on Kubernetes","Run:ai (independent, commercial)","runai"],["k8sdev","How a pod asks for a GPU","device plugin: nvidia.com/gpu: 1","gpuop"],["slurm","Slurm, the HPC scheduler","Slurm (SchedMD, independent)","slurm"],["slurmk8s","Slurm on a Kubernetes cluster","SUNK (CoreWeave only)","sunk"],["aws","Resilient training cluster on AWS","ParallelCluster (you run Slurm)","pcluster"],["ray","Python distributed runtime","Ray (Anyscale)","ray"],["platform","All-in-one training platform","Determined (HPE, releasing)","determined"],["trackbig","Hosted tracker for huge runs","Neptune","neptune"],["track","Default hosted tracker","Weights & Biases (independent)","wandb"],["s3local","Self-hosted S3 for dev and on-prem","MinIO (open source)","minio"],["flow","Workflow orchestrator","Airflow 2","airflow"]],"ev":[["2023-11","aws","SageMaker HyperPod (Slurm, managed node replacement)","hyperpod","AWS launches SageMaker HyperPod: Slurm clusters whose faulty nodes are replaced and jobs resumed for you."],["2024-09","aws","HyperPod with Slurm or EKS","hyperpod","HyperPod adds Amazon EKS as an orchestrator (GA 2024-09-10)."],["2024-11","slurmk8s","Slinky (open source, SchedMD) or SUNK","slinky","SchedMD open-sources Slinky: Slurm on any Kubernetes cluster."],["2024-12","k8sgpu","NVIDIA Run:ai","runai","NVIDIA completes the Run:ai acquisition (2024-12-30)."],["2025-03","platform","Determined (no release since March 2025)","determined","Determined 0.38.1 (2025-03-19) is its last release; no commits since."],["2025-04","k8sgpu","KAI Scheduler (open source) or Kueue","kai","NVIDIA open-sources the Run:ai scheduler as KAI Scheduler (Apache-2.0)."],["2025-04","flow","Airflow 3","airflow","Airflow 3.0 ships (2025-04-22): Task Execution API, DAG versioning, new SDK."],["2025-05","track","Weights & Biases (owned by CoreWeave)","wandb","CoreWeave completes its acquisition of Weights & Biases."],["2025-07","k8strain","TrainJob (Trainer v2) on JobSet, admitted by Kueue","trainer","Kubeflow Trainer v2.0: one TrainJob API run as a JobSet; v1 becomes legacy."],["2025-09","k8sdev","device plugin, or DRA ResourceClaims (GA)","k8s","Kubernetes 1.34: Dynamic Resource Allocation goes GA."],["2025-10","ray","Ray (PyTorch Foundation project)","ray","Ray joins the PyTorch Foundation (2025-10-22)."],["2025-12","s3local","MinIO in maintenance mode","minio","MinIO puts the open-source server in maintenance mode, after stopping binary releases."],["2025-12","slurm","Slurm (SchedMD, part of NVIDIA)","slurm","NVIDIA acquires SchedMD (2025-12-15) and says Slurm stays open source."],["2026-03","trackbig","shut down: export to W&B or MLflow","neptune","Neptune, bought by OpenAI, turns off its hosted app and API and deletes hosted data."],["2026-04","s3local","MinIO archived: AIStor, Ceph RGW, SeaweedFS or Garage","minio","minio/minio is archived: 'THIS REPOSITORY IS NO LONGER MAINTAINED'."]],"vers":{"note":"Read on 2026-10-16 from the topic's shared lab environment (Apple M1 Pro, Docker Desktop): pip metadata, sinfo -V, kubectl version and controller image tags. 'Latest release' is this map's column.","rows":[{"id":"ray","name":"Ray","how":"pip, shared venv","lab":"2.59.0","same":true,"gap":"","note":""},{"id":"torchrun","name":"PyTorch (torchrun)","how":"pip, shared venv","lab":"2.14.1","same":true,"gap":"","note":""},{"id":"slurm","name":"Slurm","how":"sinfo -V in the controller container (Debian package)","lab":"24.11.5","same":false,"gap":"older than latest 26.05.5","note":"Debian 13 packages Slurm 24.11; SchedMD's September 2026 patch releases (2026-09-02) were for 26.05, 25.11 and 25.05, not 24.11. Fine for teaching sbatch, srun, backfill and fairshare."},{"id":"k8s","name":"Kubernetes (kind)","how":"kubectl version, server","lab":"v1.37.0","same":false,"gap":"same release series (1.37), older patch","note":"kind node image"},{"id":"jobset","name":"JobSet","how":"controller image tag","lab":"v0.13.0","same":true,"gap":"","note":""},{"id":"kueue","name":"Kueue","how":"controller image tag","lab":"v0.20.2","same":true,"gap":"","note":""}]}};
